RECORDS = [('解剖学姿势、方位与切面', '解剖学基础', '绪论', '人体结构以标准解剖学姿势统一描述；内外侧参照正中面，近远侧参照肢体根部。矢状、冠状、水平面分别用于描述不同方向的切面。', ['能按标准姿势判断方位。', '能区分三类基本切面。'], Q('将人体分为前、后两部分的切面叫什么？', '冠状面', ['矢状面', '水平面', '正中矢状面'], '冠状面沿左右方向展开，将人体分为前、后部分。'), Q('按标准解剖学姿势描述上肢，哪句话正确？', '拇指位于小指的外侧', ['拇指位于小指的内侧', '肘位于腕的远侧', '手掌朝向后方'], '标准姿势掌心向前，拇指远离身体正中面，位于外侧；肘较腕近侧。')), ('骨、关节与骨骼肌的运动配合', '运动系统', '运动系统', '骨构成杠杆，关节提供骨间连接及运动条件，骨骼肌收缩经肌腱传递牵引力。滑膜关节具有相对的关节面、关节囊和关节腔等结构。', ['能识别滑膜关节的基本结构。', '能解释肌肉牵引骨产生运动的关系。'], Q('连接骨骼肌与骨并传递肌肉牵引力的主要结构是什么？', '肌腱', ['关节软骨', '韧带', '关节囊的纤维层'], '肌腱将肌肉产生的牵引力传递给骨。'), Q('一块跨越肘关节的骨骼肌收缩使前臂运动，最合适的结构解释是哪项？', '肌肉经肌腱牵引骨，以关节为运动连接部位', ['韧带主动收缩，肌腱只起润滑作用', '关节软骨主动缩短，肌肉仅被动移动', '骨骼肌收缩主要把骨推离附着处'], '骨骼肌主要产生牵引力；骨、关节与肌共同构成运动装置。'), [(1, '描述肢体运动前需要统一位置和方向术语')]), ('消化管与消化腺的连接', '内脏系统', '消化系统', '消化管由口腔延续至肛门，肝、胰等消化腺通过导管参与消化。小肠承担重要的消化吸收功能，胆汁经胆道进入十二指肠。', ['能排列主要消化管段。', '能区分消化管与消化腺。'], Q('食物离开胃后首先进入哪一段消化管？', '十二指肠', ['空肠', '回肠', '盲肠'], '胃幽门与十二指肠相接，随后才进入空肠和回肠。'), Q('哪一组都属于消化腺，而不是供食物直接通过的消化管？', '肝和胰', ['胃和空肠', '食管和直肠', '十二指肠和结肠'], '肝和胰分泌的消化液经导管进入消化管，食物不直接通过两者的实质。')), ('呼吸道、肺与胸膜', '内脏系统', '呼吸系统', '空气经呼吸道到达肺内远端气体交换区域。左右肺各有独立胸膜囊；胸膜脏层覆盖肺表面，壁层衬贴胸壁等结构内面。', ['能区分气体传导与交换区域。', '能识别胸膜脏层和壁层的关系。'], Q('紧贴并覆盖肺表面的胸膜是哪一层？', '脏胸膜', ['壁胸膜的肋部', '心包纤维层', '腹膜壁层'], '脏胸膜覆盖肺表面并进入叶间裂；壁胸膜衬于胸壁等结构内面。'), Q('一幅气流路径图把气管直接连到肺泡并省略全部中间分支，遗漏的主要层级是什么？', '支气管及细支气管系统', ['鼻腔、咽及喉的上游通路', '肺动脉及肺静脉的血管分支', '胸膜腔及胸膜隐窝'], '气管分为主支气管，经多级支气管和细支气管分支，逐步通向气体交换区域。')), ('肾与尿液引流通路', '内脏系统', '泌尿系统', '肾形成尿液，尿液经肾盏、肾盂和输尿管进入膀胱，再通过尿道排出。输尿管连接肾盂与膀胱，尿道连接膀胱与体外。', ['能排列尿液引流路径。', '能区分输尿管与尿道。'], Q('连接肾盂与膀胱的管道是什么？', '输尿管', ['尿道', '输精管', '输卵管'], '输尿管将尿液从肾盂引向膀胱；尿道负责从膀胱通向体外。'), Q('不考虑尿液在肾内的形成过程，下列引流次序哪项正确？', '肾盂→输尿管→膀胱→尿道', ['肾盂→尿道→膀胱→输尿管', '膀胱→肾盂→尿道→输尿管', '输尿管→膀胱→肾盂→尿道'], '肾盂位于肾盏之后，随后通过输尿管、膀胱和尿道构成引流路线。')), ('生殖器官与配子运输', '内脏系统', '生殖系统', '睾丸产生精子，附睾参与精子成熟与储存，输精管承担输送。卵巢产生卵母细胞，输卵管连接腹膜腔侧与子宫，子宫为胚胎与胎儿发育提供场所。', ['能识别男女生殖腺。', '能区分配子产生部位与运输通道。'], Q('女性生殖系统中产生卵母细胞的主要器官是什么？', '卵巢', ['子宫内膜', '输卵管', '子宫颈'], '卵巢为女性生殖腺，卵母细胞在其中发育。'), Q('关于男性生殖系统的分工，哪项配对正确？', '睾丸—产生精子；输精管—输送精子', ['附睾—产生精子；睾丸—仅储存精子', '精囊—产生精子；输精管—分泌全部精液', '前列腺—产生精子；附睾—仅输送尿液'], '精子产生于睾丸，随后经附睾等生殖管道运输；附属性腺分泌液体但不产生精子。')), ('内分泌器官的定位与分泌方式', '内分泌系统', '内分泌系统', '内分泌腺通常不以导管向体表或器官腔排送分泌物，其激素经体液参与调节。甲状腺、甲状旁腺、垂体及肾上腺等具有不同位置和结构。', ['能区分内分泌与外分泌的结构方式。', '能识别常见内分泌器官的位置关系。'], Q('哪种描述符合内分泌腺的一般分泌方式？', '分泌物进入组织液并可经血液运输', ['分泌物必须经导管排到体表', '分泌物主要经专门导管排入器官腔', '激素必须沿神经轴突运输至全身靶细胞'], '内分泌腺通常无输出导管，激素释放到体液中；这与外分泌腺的导管途径不同。'), Q('一张解剖图标出位于左右肾上方的成对腺体，该结构应是？', '肾上腺', ['甲状腺', '垂体', '胸腺'], '肾上腺位于肾的上方附近；名称与解剖位置相应，但其功能不等同于肾。')), ('心腔、瓣膜与血流方向', '脉管系统', '脉管系统', '心脏分为左右心房和心室。右心接受体循环静脉回流并将血液送入肺循环，左心接受肺静脉回流并将血液送入体循环；瓣膜维持相应的单向流动。', ['能追踪肺循环和体循环的连接。', '能识别房室瓣与动脉瓣的位置。'], Q('正常情况下，血液从右心室首先进入哪条大血管？', '肺动脉干', ['主动脉', '上腔静脉', '肺静脉'], '右心室经肺动脉瓣将血液射入肺动脉干。'), Q('某血细胞刚由肺静脉回到心脏，接下来正常依次经过哪些结构？', '左心房→二尖瓣→左心室', ['右心房→三尖瓣→右心室', '左心室→三尖瓣→右心房', '右心室→肺动脉瓣→左心房'], '肺静脉开口于左心房，血液经二尖瓣进入左心室。')), ('动静脉命名与肝门静脉系统', '脉管系统', '脉管系统', '动脉与静脉按血流相对心脏的方向区分，不能仅按含氧量命名。肝门静脉收集消化管部分区域等的静脉血并送入肝窦，再经肝静脉回流。', ['能用血流方向定义动脉和静脉。', '能说明门静脉与肝静脉的不同。'], Q('区分动脉和静脉时，最基本的解剖学依据是什么？', '血液流离心脏还是流向心脏', ['血液是否呈鲜红色', '血液是否一定富含氧', '管壁是否具有静脉瓣'], '动脉将血液带离心脏，静脉把血液带向心脏；肺循环说明含氧量不是命名标准。'), Q('小肠吸收的多数水溶性营养物质进入血液后，通常首先经哪条静脉系统到肝？', '肝门静脉系统', ['肝静脉系统直接逆行入肝', '下腔静脉直接分支入肝', '肺静脉系统'], '消化管相关静脉血经肝门静脉入肝；多数长链脂质的淋巴转运不属于题中限定情形。'), [(8, '先理解两大循环，才能比较门静脉等局部回流路径')]), ('淋巴回流与淋巴器官', '脉管系统', '脉管系统', '淋巴管将部分组织液及所携物质回输至静脉系统。淋巴结位于淋巴回流通路中；脾与血液过滤、免疫和血细胞相关过程有关。', ['能区分淋巴和血液的回流通路。', '能区分淋巴结与脾的主要结构联系。'], Q('组织间液进入淋巴管后，最终主要回流到哪里？', '静脉系统', ['动脉系统', '重新直接回到原组织间隙', '以淋巴结作为全部淋巴的最终终点'], '淋巴最终经淋巴导管注入静脉系统，参与维持体液回流。'), Q('比较淋巴结与脾时，哪项正确？', '淋巴结接收淋巴，脾主要处理血液相关抗原和血细胞', ['淋巴结主要过滤血液，脾主要过滤输入淋巴', '脾位于所有输入淋巴管的必经通路', '淋巴结是成人正常红细胞生成的主要器官'], '淋巴结与淋巴管相连；脾属于血液循环相关的淋巴器官，二者入口与任务不同。'), [(8, '理解静脉回流有助于定位淋巴的最终汇入处', 'soft')]), ('视器与前庭蜗器的结构分工', '感觉器', '感觉器', '眼的屈光结构将光线投向视网膜，视网膜包含感光细胞。内耳耳蜗与听觉有关，前庭和半规管参与头位及运动信息的感受。', ['能区分屈光结构与感光组织。', '能区分内耳听觉与平衡相关部分。'], Q('眼内包含视杆和视锥等感光细胞的组织是什么？', '视网膜', ['角膜基质', '晶状体', '巩膜'], '视网膜中的视杆和视锥完成光信号感受；角膜、晶状体主要参与屈光。'), Q('关于内耳结构分工，下列哪项正确？', '耳蜗与听觉有关，半规管与角加速度感受有关', ['耳蜗主要感受头位，半规管主要完成听觉', '耳蜗把声音传给鼓膜，鼓膜是内耳平衡感受器', '半规管主要感受直线加速度，耳蜗主要感受角加速度'], '耳蜗含听觉感受结构；半规管系统的壶腹嵴参与感受头部角加速度。')), ('中枢、周围神经与反射弧结构', '神经系统', '神经系统', '脑和脊髓组成中枢神经系统，脑神经、脊神经等属于周围神经系统。反射弧涉及感受器、传入通路、中枢联系、传出通路和效应器。', ['能区分中枢与周围神经结构。', '能排列典型反射弧的组成。'], Q('哪组结构共同构成中枢神经系统？', '脑和脊髓', ['脑神经和脊神经', '脑与脊神经节', '脊髓与交感神经干'], '中枢神经系统的基本组成是脑和脊髓。'), Q('典型躯体反射的信息传递方向，哪项正确？', '感受器→传入神经→中枢→传出神经→骨骼肌', ['骨骼肌→传出神经→感受器→中枢', '中枢→传入神经→感受器→骨骼肌', '传出神经→感受器→传入神经→中枢'], '传入通路把感受信息送向中枢，传出通路将中枢活动传给效应器；实际反射环路还可有反馈。'))]
